function model(p) {
  // Illustrative sales data: two teams, 200 deals each, two deal sizes. Large deals are harder to win for everyone.
  // Team A is slightly better in each size; the slider moves Team A's mix of large deals. Team B's mix is fixed at 25% large.
  const N = 200;
  const team = (name, nLarge, rSmall, rLarge) => {
    const nSmall = N - nLarge, winSmall = Math.round(nSmall * rSmall), winLarge = Math.round(nLarge * rLarge);
    return { name, n: N, nSmall, nLarge, winSmall, winLarge, wins: winSmall + winLarge,
      rateSmall: winSmall / nSmall, rateLarge: winLarge / nLarge, overall: (winSmall + winLarge) / N,
      shareSmall: nSmall / N, shareLarge: nLarge / N };
  };
  const share = Math.max(10, Math.min(90, p.shareLarge)) / 100;
  const A = team('Team A', Math.round(N * share), 0.78, 0.36);
  const B = team('Team B', 50, 0.72, 0.28);
  const view = Math.round(p.view) === 1 ? 'segments' : 'overall';
  const paradox = A.rateSmall > B.rateSmall && A.rateLarge > B.rateLarge && A.overall < B.overall;
  const f = v => (v * 100).toFixed(1) + '%', s0 = v => Math.round(v * 100) + '%';
  const lead = A.overall < B.overall ? 'Team B' : 'Team A';
  const steps = [
    { id: 'overall', start: 0, chip: 'Overall', title: 'Overall win rate', text: 'Overall, ' + lead + ' looks better: Team A wins ' + f(A.overall) + ' of its deals, Team B ' + f(B.overall) + '.' },
    { id: 'split', start: 3, chip: 'Split by size', title: 'Split by deal size', text: 'By deal size, Team A wins more often in both: small ' + f(A.rateSmall) + ' vs ' + f(B.rateSmall) + ', large ' + f(A.rateLarge) + ' vs ' + f(B.rateLarge) + '.' },
    { id: 'mix', start: 6, chip: 'The mix', title: 'Look at the mix', text: s0(A.shareLarge) + ' of Team A’s deals are large (the hard kind) versus ' + s0(B.shareLarge) + ' of Team B’s.' },
    { id: 'weighted', start: 9, chip: 'Weighted average', title: 'Overall = mix-weighted average', text: 'Each overall rate is the segment rates weighted by the mix. Team A: ' + s0(A.shareSmall) + ' × ' + f(A.rateSmall) + ' + ' + s0(A.shareLarge) + ' × ' + f(A.rateLarge) + ' = ' + f(A.overall) + '.' }
  ];
  const summary = paradox
    ? 'Simpson’s paradox: Team A wins more often in every deal size, yet ' + f(A.overall) + ' vs ' + f(B.overall) + ' overall, because ' + s0(A.shareLarge) + ' of its deals are large.'
    : 'No paradox at this mix: Team A wins more often in each deal size and overall (' + f(A.overall) + ' vs ' + f(B.overall) + ').';
  const formula = t => s0(t.shareSmall) + ' × ' + f(t.rateSmall) + ' + ' + s0(t.shareLarge) + ' × ' + f(t.rateLarge) + ' = ' + f(t.overall);
  A.formula = formula(A); B.formula = formula(B);
  return { teams: [A, B], view, paradox, steps, duration: 12, summaryAt: 11, markers: steps.map(s => s.start), summary };
}

checkCode:
function check(p) {
  const m = model(p), [A, B] = m.teams, pc = v => (v * 100).toFixed(1) + '%';
  // 1. Team A beats Team B within each deal size.
  const segOk = A.rateSmall > B.rateSmall && A.rateLarge > B.rateLarge;
  // 2. Each overall rate equals the mix-weighted average of that team's segment rates.
  const wavg = t => t.shareSmall * t.rateSmall + t.shareLarge * t.rateLarge;
  const avgOk = m.teams.every(t => Math.abs(t.overall - wavg(t)) < 1e-12 && t.nSmall + t.nLarge === t.n && t.winSmall <= t.nSmall && t.winLarge <= t.nLarge);
  // 3. The paradox flag matches the numbers.
  const flagOk = m.paradox === (A.overall < B.overall);
  return { pass: segOk && avgOk && flagOk,
    detail: 'Team A wins ' + pc(A.rateSmall) + ' vs ' + pc(B.rateSmall) + ' of small deals and ' + pc(A.rateLarge) + ' vs ' + pc(B.rateLarge) + ' of large ones, ' + (m.paradox ? 'yet' : 'and') + ' overall ' + pc(A.overall) + ' = ' +
      Math.round(A.shareSmall * 100) + '% × ' + pc(A.rateSmall) + ' + ' + Math.round(A.shareLarge * 100) + '% × ' + pc(A.rateLarge) + ' vs Team B ' + pc(B.overall) + (m.paradox ? ' (paradox).' : ' (no paradox at this mix).') };
}
